// Browser end-to-end tests against the production build served by FastAPI.
// Chrome's fake camera plays Y4M videos generated by e2e/prepare.mjs, so the real
// camera -> MediaPipe -> OpenCV.js -> API -> UI pipeline runs without a physical camera.
// Run with `npm run e2e` (after `npm run build`).
import { defineConfig } from "@playwright/test";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = fileURLToPath(new URL(".", import.meta.url));
const MEDIA = resolve(__dirname, "e2e/.media");
const python =
  process.env.GLOVESIZE_PYTHON ??
  resolve(__dirname, process.platform === "win32" ? "../backend/.venv/Scripts/python.exe" : "../backend/.venv/bin/python");

const server = (port: number, env: Record<string, string> = {}) => ({
  command: `"${python}" -m uvicorn glovesize.api:app --host 127.0.0.1 --port ${port}`,
  cwd: resolve(__dirname, "../backend"),
  url: `http://127.0.0.1:${port}/api/health`,
  reuseExistingServer: false,
  timeout: 60_000,
  // The browser tests keep the six-size demo chart: their expectations are written for it.
  env: { GLOVESIZE_DEFAULT_CHART: "demo-length-v1", ...env },
});

const fakeCamera = (video: string) => ({
  args: ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream", `--use-file-for-fake-video-capture=${video}`],
});

export default defineConfig({
  testDir: "e2e",
  timeout: 150_000,
  expect: { timeout: 60_000 },
  workers: 1,
  reporter: [["list"]],
  use: {
    channel: process.env.E2E_CHANNEL ?? "chrome",
    headless: true,
    permissions: ["camera"],
    screenshot: "only-on-failure",
  },
  webServer: [
    server(8765),
    // Relaxed world-landmark gates for the sample hand photo (see e2e/prepare.mjs).
    server(8766, {
      GLOVESIZE_CONFIG_DIR: resolve(MEDIA, "config-relaxed"),
      GLOVESIZE_VALIDATION_ENABLED: "true",
      GLOVESIZE_PILOT_REMOTE_ENABLED: "true",
      GLOVESIZE_VALIDATION_PATH: resolve(MEDIA, "validation", "records.jsonl"),
    }),
  ],
  projects: [
    {
      name: "synthetic-coin",
      testMatch: /(app|responsive)\.spec\.ts/,
      use: { baseURL: "http://127.0.0.1:8765", launchOptions: fakeCamera(resolve(MEDIA, "coin.y4m")) },
    },
    {
      name: "hand-photo",
      testMatch: /(full-scan|three-views|side-of-hand|validation|pilot)\.spec\.ts/,
      use: { baseURL: "http://127.0.0.1:8766", launchOptions: fakeCamera(resolve(MEDIA, "hand.y4m")) },
    },
  ],
});
